import React from "react";
import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { ArrowLeft, Clock, Calendar, User, MessageCircle, Share2 } from "lucide-react";
import { Metadata } from "next";

// --- ТИПЫ ---
// ⚠️ В Next.js 15+ params - это Promise
type Props = {
  params: Promise<{ slug: string }>;
};

// 🛠️ Хелпер для создания полных ссылок (для SEO)
const getAbsoluteUrl = (path: string) => {
  const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || 'https://evatur.club';
  if (path.startsWith('http')) return path;
  return `${baseUrl}${path.startsWith('/') ? '' : '/'}${path}`;
};

// --- 1. ГЕНЕРАЦИЯ МЕТАДАННЫХ (SEO) ---
export async function generateMetadata({ params }: Props): Promise {
  // ⚠️ Ждем разрешения параметров
  const { slug } = await params;

  // Декодируем slug (на случай кириллицы)
  const decodedSlug = decodeURIComponent(slug);

  const post = await prisma.blog.findUnique({
    where: { slug: decodedSlug },
  });

  if (!post) return { title: "Статья не найдена" };

  const ogImage = post.image ? getAbsoluteUrl(post.image) : undefined;

  return {
    title: post.title,
    description: post.excerpt,
    openGraph: {
      title: post.title,
      description: post.excerpt,
      type: "article",
      url: getAbsoluteUrl(`/blog/${post.slug}`),
      images: ogImage ? [{ url: ogImage }] : [],
    },
  };
}

// --- 2. ПОЛУЧЕНИЕ ДАННЫХ ---
async function getPost(slug: string) {
  const decodedSlug = decodeURIComponent(slug);

  const post = await prisma.blog.findUnique({
    where: { slug: decodedSlug },
  });

  if (!post) return null;

  // Ищем похожие посты (исключаем текущий)
  const relatedPosts = await prisma.blog.findMany({
    where: { 
        id: { not: post.id },
    },
    orderBy: { date: "desc" },
    take: 3,
  });

  return { post, relatedPosts };
}

// --- 3. СТРАНИЦА БЛОГА ---
export default async function BlogPostPage({ params }: Props) {
  // ⚠️ Ждем разрешения параметров перед использованием
  const { slug } = await params;

  const data = await getPost(slug);

  if (!data) {
    notFound();
  }

  const { post, relatedPosts } = data;

  return (


      {/* HEADER IMAGE / HERO */}










              Назад в блог





                 {post.category}


                  {post.read_time} мин


                  {new Date(post.date).toLocaleDateString('ru-RU')}





              {post.title}


            {/* AUTHOR */}




                  {post.author_image ? (

                  ) : (


                  )}




{post.author_name || 'Команда EVA'}

{post.author_role || 'Турклуб'}





      {/* CONTENT */}





          {/* ARTICLE BODY */}




             {/* SHARE / TAGS */}




                   Поделиться статьей:









          {/* SIDEBAR */}

             {/* Related Posts */}
             {relatedPosts.length > 0 && (



Читайте также


                       {relatedPosts.map(rel => (









                                   {rel.title}

                                {new Date(rel.date).toLocaleDateString('ru-RU')}


                       ))}


             )}





  );
}



