      */}
      {!isTourPage && (
        <>
          {promo}
          {footer}
        </>
      )}

  );
}



"use client";

import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Compass, MessageCircle, X, Check, ArrowLeft, Loader2, BookOpen, ChevronRight, Send, AlertCircle, Map } from "lucide-react";
import Link from "next/link";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// ==================== ТИПЫ И КОНСТАНТЫ (LOGIC KEPT) ====================

type TourAnswers = {
  experience: string;
  fears: string;
  pace: string;
  company: string;
  focus: string;
  readiness: string;
};

type TourRecommendation = {
  title: string;
  description: string;
  link: string;
  emoji: string;
  features: string[];
};

type FormErrors = Record;

const steps = [
  {
    question: "Ты когда-нибудь ходил в походы раньше?",
    key: "experience" as keyof TourAnswers,
    type: "select" as const,
    options: ["никогда", "редко", "часто"],
  },
  {
    question: "Что тебя сейчас волнует больше всего?",
    subtitle: "Не стесняйся, мы все через это проходили",
    key: "fears" as keyof TourAnswers,
    type: "text" as const,
    placeholder: "Например: боюсь не справиться физически...",
  },
  {
    question: "Как ты хочешь, чтобы проходил поход?",
    key: "pace" as keyof TourAnswers,
    type: "select" as const,
    options: ["спокойно", "средний темп", "драйв"],
  },
  {
    question: "С кем ты планируешь поехать?",
    key: "company" as keyof TourAnswers,
    type: "select" as const,
    options: ["один/одна", "с парой", "с друзьями", "с детьми"],
  },
  {
    question: "Что для тебя самое важное в поездке?",
    key: "focus" as keyof TourAnswers,
    type: "select" as const,
    options: ["природа/виды", "люди/тусовка", "перезагрузка", "испытание себя"],
  },
  {
    question: "Когда ты готов отправиться?",
    key: "readiness" as keyof TourAnswers,
    type: "select" as const,
    options: ["в ближайшие выходные", "в этом месяце", "просто смотрю"],
  },
];

// ==================== MAIN COMPONENT ====================

export default function PromoBlock() {
  const [openTour, setOpenTour] = useState(false);
  const [openAsk, setOpenAsk] = useState(false);

  // States для Тура (Квиз)
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Partial>({});
  const [recommendation, setRecommendation] = useState(null);
  const [loadingTour, setLoadingTour] = useState(false);

  // States для Вопроса (Ask)
  const [askName, setAskName] = useState("");
  const [askContact, setAskContact] = useState("");
  const [askMessage, setAskMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [askSuccess, setAskSuccess] = useState(false);
  const [errors, setErrors] = useState({});

  // Refs
  const firstInputRef = useRef(null);
  const textInputRef = useRef(null);

  // --- ЭФФЕКТЫ (СОХРАНЕНЫ) ---

  // 1. Фокус
  useEffect(() => {
    if (openAsk && firstInputRef.current) setTimeout(() => firstInputRef.current?.focus(), 100);
    if (openTour && steps[step]?.type === "text" && textInputRef.current) setTimeout(() => textInputRef.current?.focus(), 100);
  }, [openAsk, openTour, step]);

  // 2. Сохранение прогресса
  useEffect(() => {
    if (openTour) localStorage.setItem("tour-quiz-progress", JSON.stringify({ step, answers }));
  }, [step, answers, openTour]);

  // 3. Восстановление
  useEffect(() => {
    const saved = localStorage.getItem("tour-quiz-progress");
    if (saved && openTour && step === 0) {
      try {
        const { step: savedStep, answers: savedAnswers } = JSON.parse(saved);
        if (savedStep > 0 && confirm("Продолжить заполнение анкеты?")) {
          setStep(savedStep);
          setAnswers(savedAnswers);
        }
      } catch (e) { console.error(e); }
    }
  }, [openTour]);

  // 4. Analytics
  useEffect(() => {
    if (openTour) {
      // @ts-ignore
      window.gtag?.("event", "quiz_started", { event_category: "engagement" });
    }
  }, [openTour]);


  // --- ЛОГИКА (СОХРАНЕНА) ---

  const handleNextStep = (answer: string) => {
    if (!answer) return;
    const newAnswers = { ...answers, [steps[step].key]: answer };
    setAnswers(newAnswers);

    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      finishTourQuiz(newAnswers);
    }
  };

  const finishTourQuiz = async (finalAnswers: Partial) => {
    setLoadingTour(true);
    const rec = getRecommendation(finalAnswers);

    try {
      await fetch("/api/tour-quiz", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          answers: finalAnswers,
          recommendation: rec,
          timestamp: new Date().toISOString(),
        }),
      });
      // @ts-ignore
      window.gtag?.("event", "quiz_completed", { event_category: "conversion", label: rec.title });
    } catch (e) { console.error("Error saving quiz:", e); }

    setTimeout(() => {
      setRecommendation(rec);
      setLoadingTour(false);
      localStorage.removeItem("tour-quiz-progress");
    }, 1000);
  };

  const getRecommendation = (ans: Partial): TourRecommendation => {
    if (ans.company === "с детьми") return { title: "Семейный выезд / Детский лагерь", description: "Безопасные маршруты, где детям весело, а родители отдыхают.", link: "/tours?type=kids", emoji: "🐣", features: ["Анимация", "Легкий рюкзак", "Комфортная ночевка"] };
    if (ans.focus === "испытание себя" || ans.pace === "драйв") return { title: "Восхождение или Экспедиция", description: "Для тех, кто готов бросить вызов и увидеть то, что скрыто от других.", link: "/tours?type=climbing", emoji: "🏔️", features: ["Высокие горы", "Преодоление", "Команда единомышленников"] };
    if (ans.focus === "природа/виды" && (ans.pace === "спокойно" || ans.pace === "средний темп")) return { title: "Живописный сплав", description: "Вода, скалы и полное медитативное погружение. Греби и наслаждайся.", link: "/tours?type=rafting", emoji: "🛶", features: ["Виды с воды", "Без тяжелых рюкзаков", "Вечерняя гитара"] };
    if (ans.experience === "никогда" || ans.readiness === "в ближайшие выходные") return { title: "Тур выходного дня (Weekend)", description: "Идеальный старт: короткое путешествие, чтобы влюбиться в походы.", link: "/tours?type=weekend", emoji: "🎒", features: ["Всего 2 дня", "Автосопровождение", "Вкусная еда"] };
    return { title: "Классический пеший поход", description: "Золотая середина. Баланс нагрузки, красот и походной романтики.", link: "/tours?type=hiking", emoji: "🥾", features: ["Настоящая романтика", "Ночевка в палатках", "Перезагрузка головы"] };
  };

  const handleCloseTourModal = () => {
    setOpenTour(false);
    setStep(0);
    setAnswers({});
    setRecommendation(null);
  };

  const handleAskSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: FormErrors = {};
    if (!askName.trim()) newErrors.name = "Как к тебе обращаться?";
    if (!askContact.trim()) newErrors.contact = "Куда нам ответить?";
    if (!askMessage.trim()) newErrors.message = "Напиши хоть пару слов";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsSubmitting(true);
    setErrors({});

    try {
        const response = await fetch("/api/questions", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              name: askName,
              contact: askContact,
              question: askMessage,
              timestamp: new Date().toISOString(),
            }),
        });
        if (!response.ok) throw new Error("Ошибка отправки");
        // @ts-ignore
        window.gtag?.("event", "question_submitted", { event_category: "conversion" });

        setAskSuccess(true);
        setTimeout(() => {
            setOpenAsk(false);
            setAskSuccess(false);
            setAskName("");
            setAskContact("");
            setAskMessage("");
        }, 3000);

    } catch (error) {
        console.error("Error:", error);
        setErrors({ submit: "Не удалось отправить. Напишите нам в Telegram!" });
    } finally {
        setIsSubmitting(false);
    }
  };

  // ==================== NEW UI RENDER ====================

  return (



      {/* Background Ambience */}








        {/* HEADER */}





               Navigation



            Не знаете с чего начать?



            Три простых способа найти своё идеальное приключение



        {/* BENTO GRID */}



          {/* 1. QUIZ (PRIMARY) - TEAL ACCENT */}

 setOpenTour(true)}
            className="
                group cursor-pointer relative overflow-hidden rounded-3xl
                bg-slate-900/50 backdrop-blur-xl border border-teal-500/20
                hover:border-teal-500/50 hover:shadow-[0_0_40px_-10px_rgba(20,184,166,0.2)]
                transition-all duration-500
            "
          >
            {/* Giant Icon Background */}


            {/* Content */}









Подобрать тур

Пройди быстрый тест и получи идеальный маршрут от нашего AI.


               {/* Button Look */}


                  Начать квиз







            {/* Radar Pulse Effect */}






