"use client";

import { useState, useEffect, useRef } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { X, Send, CheckCircle2, AlertCircle } from "lucide-react";
import { sendJoinTeamAction } from "@/features/admin/actions";

interface JoinTeamModalProps {
  open: boolean;
  onClose: () => void;
}

type FormStatus = 'idle' | 'loading' | 'success' | 'error';

export default function JoinTeamModal({ open, onClose }: JoinTeamModalProps) {
  const [status, setStatus] = useState('idle');
  const [error, setError] = useState(null);
  const [formData, setFormData] = useState({ name: '', telegram: '' });
  const modalRef = useRef(null);
  const firstInputRef = useRef(null);

  // Блокировка прокрутки body при открытии модалки
  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
      // Автофокус на первое поле
      setTimeout(() => firstInputRef.current?.focus(), 100);
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [open]);

  // Закрытие по Escape
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && open) {
        handleClose();
      }
    };
    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [open]);

  const handleClose = () => {
    if (status === 'loading') return; // Не закрываем во время отправки
    setStatus('idle');
    setError(null);
    setFormData({ name: '', telegram: '' });
    onClose();
  };

  const validateTelegram = (value: string): boolean => {
    // Telegram username: начинается с @ или без, 5-32 символа, только латиница, цифры, подчёркивания
    const telegramRegex = /^@?[a-zA-Z0-9_]{5,32}$/;
    return telegramRegex.test(value);
  };

  const handleInputChange = (e: React.ChangeEvent) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Сбрасываем ошибку при вводе
    if (error) setError(null);
  };

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    // Валидация
    if (formData.name.trim().length < 2) {
      setError('Имя должно содержать минимум 2 символа');
      return;
    }

    if (!validateTelegram(formData.telegram)) {
      setError('Укажите корректный Telegram (например: @username или username)');
      return;
    }

    setStatus('loading');
    setError(null);

    const submitData = new FormData();
    submitData.append('name', formData.name.trim());
    submitData.append('telegram', formData.telegram.trim().replace(/^@/, '')); // Убираем @ если есть

    try {
      const res = await sendJoinTeamAction(Object.fromEntries(submitData));

      if (res.success) {
        setStatus('success');
        // Закрываем модалку через 2 секунды после успеха
        setTimeout(() => {
          handleClose();
        }, 2000);
      } else {
        setStatus('error');
        setError(res.error || 'Не удалось отправить заявку. Попробуйте позже');
      }
    } catch (err) {
      setStatus('error');
      setError('Произошла ошибка. Проверьте подключение к интернету');
    }
  }

  return (

      {open && (
        <>
          {/* Backdrop с blur */}


          {/* Modal */}



              {/* Светящийся эффект вокруг модалки */}



              {/* Основной контент */}


                {/* Декоративный градиент сверху */}





                  {/* Кнопка закрытия */}




                  {/* Условный рендер: форма / успех */}

                    {status === 'success' ? (
                      // Экран успеха






                          Заявка отправлена!



                          Мы свяжемся с тобой в Telegram в ближайшее время


                    ) : (
                      // Форма

                        {/* Заголовок */}




                              Присоединяйся



                            Стань частью{" "}
                            команды мечты


                            Оставь контакты, и мы обсудим, как ты можешь изменить 
                            жизнь людей через горы



                        {/* Форма */}

                          {/* Поле имени */}


                              Как тебя зовут?




                          {/* Поле Telegram */}


                              Твой Telegram




                                @





                              Без пробелов, 5-32 символа



                          {/* Ошибка */}

                            {error && (



{error}

                            )}


                          {/* Кнопка отправки */}

                            {/* Анимированный блик */}
                            {status !== 'loading' && (

                            )}


                              {status === 'loading' ? (
                                <>




                                  Отправляем...
                                </>
                              ) : (
                                <>
                                  Отправить заявку

                                </>
                              )}




                    )}





        </>
      )}

  );
}



'use server'

import { revalidatePath } from 'next/cache';
import { prisma } from '@/lib/prisma';
import { BookingStatus } from '@prisma/client';

// ==========================================
// 1. БРОНИРОВАНИЯ (CRM)
// ==========================================

export async function getRegistrationsAction() {
  try {
    const rawData = await prisma.booking.findMany({
      include: {
        tour: { select: { title: true, dates: true } }
      },
      orderBy: { createdAt: 'desc' }
    });

    const data = rawData.map((item) => {
        // Достаем первую дату из JSON массива dates
        const dates = (item.tour?.dates as any[]) || [];
        const firstDate = dates[0]?.start ? new Date(dates[0].start) : null;

        // Разбираем JSON билетов
        const tickets = (item.tickets as any) || {};

        return {
          id: item.id,
          user_name: item.name,
          user_phone: item.phone,
          status: item.status || 'pending',
          created_at: item.createdAt,

          tickets_adult: tickets.adult || 0,
          tickets_child: tickets.child || 0,
          total_price: item.totalPrice,

          event_id: item.tourId,
          tour: item.tour ? { 
            title: item.tour.title, 
            date: firstDate
          } : undefined
        };
    });

    return { data };
  } catch (error: any) {
    console.error("Get Registrations Error:", error);
    return { error: error.message };
  }
}

export async function updateRegistrationStatus(id: string, status: string) {
  try {
    await prisma.booking.update({
      where: { id },
      data: { status: status as BookingStatus } 
    });

    revalidatePath('/admin');
    return { success: true };
  } catch (error) {
    console.error("Update Status Error:", error);
    return { error: "Ошибка обновления статуса" };
  }
}

// ==========================================
// 2. ГИДЫ (GUIDES) — ОБНОВЛЕНО ДЛЯ "DOSSIER"
// ==========================================

export async function saveGuideAction(data: any) {
  try {
    const { id, ...rest } = data;

    // Формируем payload со всеми новыми полями
    const payload = {
      name: rest.name,
      role: rest.role || "Guide",
      image: rest.image || null,

      // Новые поля для модалки "Досье"
      actionImage: rest.actionImage || null,
      superpower: rest.superpower || null,
      experience: rest.experience || null,
      achievements: rest.achievements || [], // Prisma ждет String[]

      bio: rest.bio || null,
      instagram: rest.instagram || null,
      telegram: rest.telegram || null,
      contact: rest.contact || null,

      isActive: true
    };

    if (id) {
      // Обновление существующего гида
      await prisma.guide.update({
        where: { id: String(id) },
        data: payload
      });
    } else {
      // Создание нового гида
      await prisma.guide.create({
        data: payload
      });
    }

    revalidatePath('/admin');
    revalidatePath('/'); 
    return { success: true };
  } catch (error: any) {
    console.error("Save Guide Error:", error);
    return { error: error.message || "Ошибка при сохранении гида" };
  }
}

export async function deleteGuideAction(id: string | number) {
  try {
    await prisma.guide.delete({
      where: { id: String(id) }
    });

    revalidatePath('/admin');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error("Delete Guide Error:", error);
    return { error: "Не удалось удалить гида" };
  }
}

// ==========================================
// 3. БЛОГ (BLOG)
// ==========================================

export async function savePostAction(data: any) {
  try {
    const { id } = data;

    const slug = data.slug || data.title
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-') + '-' + Date.now().toString().slice(-4);

    const formattedData = {
      title: data.title,
      slug,
      excerpt: data.excerpt || data.content.slice(0, 150) + "...",
      content: data.content,
      category: data.category || "OTHER",
      image: data.image || null,
      read_time: parseInt(data.read_time) || 5,
      is_trending: data.is_trending === true || data.is_trending === 'on',

      // 👇 ДОБАВЛЯЕМ ПОДДЕРЖКУ НОВОГО ПОЛЯ ИЗ PRISMA
      isActive: data.is_active === true || data.is_active === 'on',

      author_name: data.author_name || "Team Eva",
      author_role: data.author_role || "Guide Club",
      author_image: data.author_image || null,

      guideId: data.guide_id || null, 

      updatedAt: new Date()
    };

    if (id) {
      await prisma.blog.update({
        where: { id },
        data: formattedData
      });
    } else {
      await prisma.blog.create({
        data: formattedData
      });
    }

    revalidatePath('/admin');
    revalidatePath('/blog');
    revalidatePath('/');
    return { success: true };
  } catch (error: any) {
    console.error("Blog Save Error:", error);
    return { error: error.message };
  }
}

export async function deletePostAction(id: string) {
  try {
    await prisma.blog.delete({ where: { id } });
    revalidatePath('/admin');
    revalidatePath('/blog');
    return { success: true };
  } catch (error) {
    return { error: "Ошибка удаления поста" };
  }
}

// ==========================================
// 4. ТУРЫ (TOURS)
// ==========================================

export async function saveTourAction(data: any) {
  try {
    // Используем динамический импорт, чтобы избежать циклических зависимостей
    // (предполагаем, что логика сохранения туров вынесена в отдельный файл)
    const { saveTour } = await import('./actions/tour'); // Проверь путь к этому файлу

    const result = await saveTour(data);

    if (!result.success) {
        throw new Error(result.error);
    }

    return { success: true };

  } catch (error: any) {
    console.error("Save Tour Error:", error);
    // Fallback: Если отдельного файла нет, можно временно вернуть ошибку или прописать логику здесь
    return { success: false, error: error.message || "Ошибка сохранения тура" };
  }
}

export async function deleteTourAction(id: string) {
  try {
    await prisma.tour.delete({ where: { id } });
    revalidatePath('/admin');
    revalidatePath('/tours');
    return { success: true };
  } catch (error) {
    return { error: "Ошибка удаления тура" };
  }
}

