"use server";

/**
 * Продвинутая отправка в Telegram с поддержкой фото и кнопок.
 */
export async function publishToTelegram(text: string, imageUrl?: string, link?: string) {
  // 1. Берем ключи (можно использовать те же переменные, что были, или новые)
  const token = process.env.TELEGRAM_BOT_TOKEN;
  // Поддерживаем оба варианта названия переменной для совместимости
  const chatId = process.env.TELEGRAM_CHANNEL_ID || process.env.TELEGRAM_CHAT_ID;

  if (!token || !chatId) {
    console.error("❌ Telegram Error: Нет ключей в .env");
    return { success: false, error: "Не настроен .env (TELEGRAM_BOT_TOKEN)" };
  }

  try {
    // 2. Определяем метод: если есть картинка -> sendPhoto, иначе -> sendMessage
    const method = imageUrl ? 'sendPhoto' : 'sendMessage';
    const url = `https://api.telegram.org/bot${token}/${method}`;

    // 3. Формируем тело запроса
    const body: any = {
      chat_id: chatId,
      parse_mode: 'HTML', // Поддержка жирного текста и ссылок
    };

    if (imageUrl) {
      body.photo = imageUrl;
      body.caption = text.slice(0, 1024); // Лимит Telegram на подпись к фото
    } else {
      body.text = text;
    }

    // 4. Добавляем Inline-кнопку (если есть ссылка)
    if (link) {
      body.reply_markup = JSON.stringify({
        inline_keyboard: [
          [{ text: "🔥 Забронировать место", url: link }]
        ]
      });
    }

    // 5. Отправка
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

    const data = await response.json();

    if (!data.ok) {
      console.error("❌ Telegram API Error:", data);
      return { success: false, error: `TG Error: ${data.description}` };
    }

    return { success: true };

  } catch (error) {
    console.error("❌ Network Error:", error);
    return { success: false, error: "Ошибка сети" };
  }
}

// Оставляем старую функцию для совместимости (если она где-то используется),
// но перенаправляем её на новую логику
export async function sendToTelegram(text: string) {
  return publishToTelegram(text);
}



'use server';

import { z } from 'zod'; // Используем Zod для валидации
import { prisma } from '@/lib/prisma'; 
import { revalidatePath } from 'next/cache';

// === 1. ZOD SCHEMA (Валидация данных с формы) ===
const tourSchema = z.object({
  id: z.string().optional(),

  // Статус
  isActive: z.boolean().default(false), // Было is_active, стало isActive

  // Шапка
  title: z.string().min(3, "Название обязательно"),
  subtitle: z.string().optional().nullable(),
  slug: z.string().min(3),

  // Маркетинг
  type: z.string().default("hiking"),
  difficulty: z.string().default("medium"),
  label: z.string().optional().nullable(),
  tags: z.array(z.string()).default([]),

  // Логистика
  location: z.string(),
  route: z.string().optional().nullable(),
  distance: z.string().optional().nullable(),
  duration: z.string().optional().nullable(),
  meetingPoint: z.string().optional().nullable(), // Было meeting_point

  // Даты (JSON)
  dates: z.array(z.object({
    start: z.string(),
    end: z.string().optional(),
    time: z.string().optional(),
    guide_id: z.string().optional().nullable(),
  })).default([]),

  // Деньги
  currency: z.string().default("RUB"),
  price: z.coerce.number(), 
  priceOld: z.coerce.number().optional().nullable(),   
  priceChild: z.coerce.number().optional().nullable(), // Было price_child
  priceFamily: z.coerce.number().optional().nullable(), // Было price_family
  priceMember: z.coerce.number().optional().nullable(), // Было price_member

  spots: z.coerce.number().default(15),
  spotsLeft: z.coerce.number().default(15), // Было spots_left

  // Медиа
  coverImage: z.string().optional().nullable(), // Было cover_image
  gallery: z.array(z.string()).default([]),

  // Контент (JSON)
  description: z.string().optional().nullable(),
  highlights: z.array(z.any()).default([]), 
  program: z.array(z.any()).default([]),    
  faq: z.array(z.any()).default([]),
  checklist: z.array(z.any()).default([]),
  documents: z.array(z.any()).default([]),

  // Списки строк
  included: z.array(z.string()).default([]), 
  additionalExpenses: z.array(z.string()).default([]), // Было additional_expenses

  // SEO
  metaTitle: z.string().optional().nullable(), // Было meta_title
  metaDesc: z.string().optional().nullable(),  // Было meta_desc
});

// === 2. СОХРАНЕНИЕ ТУРА (CREATE / UPDATE) ===
export async function saveTour(formData: any) {
  try {
    console.log("💾 Saving tour:", formData.title);

    // 1. Предобработка данных перед валидацией
    // Некоторые поля могут прийти как строки или undefined
    const rawData = {
      ...formData,
      // Приводим к camelCase, если форма шлет snake_case
      isActive: formData.isActive ?? formData.is_active ?? false,
      meetingPoint: formData.meetingPoint ?? formData.meeting_point,
      priceOld: formData.priceOld ?? formData.price_old,
      priceChild: formData.priceChild ?? formData.price_child,
      priceFamily: formData.priceFamily ?? formData.price_family,
      priceMember: formData.priceMember ?? formData.price_member,
      spotsLeft: formData.spotsLeft ?? formData.spots_left,
      coverImage: formData.coverImage ?? formData.cover_image ?? formData.image,
      additionalExpenses: formData.additionalExpenses ?? formData.additional_expenses,
      metaTitle: formData.metaTitle ?? formData.meta_title,
      metaDesc: formData.metaDesc ?? formData.meta_desc,

      // Гарантируем массивы
      tags: Array.isArray(formData.tags) ? formData.tags : [],
      included: Array.isArray(formData.included) ? formData.included : [],
    };

    // 2. Валидация Zod
    const result = tourSchema.safeParse(rawData);

    if (!result.success) {
      console.error("❌ Validation Error:", result.error.flatten());
      return { success: false, error: "Ошибка проверки данных. Проверьте обязательные поля." };
    }

    const data = result.data;

    // 🔥 3. ВЫЧИСЛЯЕМ ГЛАВНОГО ГИДА
    // Берем guide_id из первой даты. Если там нет, то null.
    // Это критически важно для отображения гида в карточке.
    const mainGuideId = data.dates?.[0]?.guide_id || null;

    // 4. ПОДГОТОВКА PAYLOAD ДЛЯ PRISMA
    // Используем camelCase ключи, как в schema.prisma
    const prismaPayload = {
      slug: data.slug,
      title: data.title,
      subtitle: data.subtitle,
      isActive: data.isActive,

      type: data.type,
      difficulty: data.difficulty,
      label: data.label,
      tags: data.tags,

      location: data.location,
      route: data.route,      
      distance: data.distance,
      duration: data.duration,
      meetingPoint: data.meetingPoint,

      dates: data.dates as any, // JSON
      guideId: mainGuideId,     // 🔥 Связь с таблицей Guide

      currency: data.currency,
      price: data.price,
      priceOld: data.priceOld,
      priceChild: data.priceChild,
      priceFamily: data.priceFamily,
      priceMember: data.priceMember,

      spots: data.spots,
      spotsLeft: data.spotsLeft,

      coverImage: data.coverImage,
      gallery: data.gallery,

      description: data.description,
      highlights: data.highlights as any, // JSON
      program: data.program as any,       // JSON
      faq: data.faq as any,               // JSON
      checklist: data.checklist as any,   // JSON
      documents: data.documents as any,   // JSON

      included: data.included,
      additionalExpenses: data.additionalExpenses,

      metaTitle: data.metaTitle,
      metaDesc: data.metaDesc,
    };

    // 5. ЗАПИСЬ В БД
    if (formData.id) {
      // Обновление
      await prisma.tour.update({
        where: { id: formData.id },
        // 👇 ДОБАВЛЕНО "as any"
        data: prismaPayload as any, 
      });
    } else {
      // Создание
      // Проверка на уникальность slug
      const existing = await prisma.tour.findUnique({ where: { slug: data.slug } });
      if (existing) {
        // Если slug занят, добавляем рандом
        prismaPayload.slug = `${data.slug}-${Math.floor(Math.random() * 1000)}`;
      }

      await prisma.tour.create({
        // 👇 ДОБАВЛЕНО "as any"
        data: prismaPayload as any, 
      });
    }

    // 6. СБРОС КЭША
    revalidatePath('/admin');
    revalidatePath('/tours');
    revalidatePath('/'); // Обновляем главную

    return { success: true };

  } catch (error: any) {
    console.error("❌ Database Error:", error);
    return { success: false, error: error.message || "Ошибка сохранения в базу" };
  }
}

// === 3. ПОЛУЧЕНИЕ СПИСКА АКТИВНЫХ ГИДОВ (Для формы) ===
export async function getActiveGuides() {
  try {
    const guides = await prisma.guide.findMany({
      where: { isActive: true },
      select: { id: true, name: true },
      orderBy: { name: 'asc' }
    });
    return guides;
  } catch (error) {
    console.error("Error fetching guides:", error);
    return [];
  }
}

// === 4. УДАЛЕНИЕ ТУРА ===
export async function deleteTour(id: string) {
  try {
    await prisma.tour.delete({ where: { id } });
    revalidatePath('/admin');
    revalidatePath('/tours');
    return { success: true };
  } catch (error) {
    console.error("Delete Error:", error);
    return { success: false, error: "Ошибка удаления" };
  }
}

// === 5. ОБНОВЛЕНИЕ СТАТУСА (Быстрый тоггл) ===
export async function updateTourStatus(id: string, isActive: boolean) {
  try {
    await prisma.tour.update({
      where: { id },
      data: { isActive },
    });
    revalidatePath('/admin');
    revalidatePath('/tours');
    return { success: true };
  } catch (error) {
    return { success: false, error: "Ошибка обновления статуса" };
  }
}



"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { Plus } from 'lucide-react';
import { useToast } from '@/shared/context/ToastContext';
import { Tour } from '@/features/tours/types'; 
import { Blog, BookingStatus, Guide, Review } from '@prisma/client'; 
import AdminNavigation from './AdminNavigation';

// VIEWS
import DashboardTab from './views/DashboardTab';
import BookingsTab from './views/BookingsTab';
import ToursTab from './views/ToursTab';
import ReviewsTab from './views/ReviewsTab';
import BlogTab from './views/BlogTab';
import GuidesTab from './views/GuidesTab';
import ContentTab from './views/ContentTab';

// FORMS & ACTIONS
import TourForm from './TourForm'; 
import GuideForm from './GuideForm';
import PostForm from './PostForm';
import ContentForm from './ContentForm';
import ReviewForm from './ReviewForm'; 
import AiAssistant from './AiAssistant';

import { saveTour, updateTourStatus } from '@/features/admin/actions/tour'; 
import { deleteTour } from '@/features/tours/actions';
import { 
  getRegistrationsAction, 
  updateRegistrationStatus, 
  saveGuideAction, 
  deleteGuideAction, 
  savePostAction, 
  deletePostAction, 
  saveContentBlockAction 
} from '@/features/admin/actions';
import { getReviews, deleteReview, upsertReview } from '@/features/reviews/actions';
import { sendToTelegram } from '@/features/admin/actions/telegram';
import { getGuides } from '@/features/guides/api';
import { getBlogPosts } from '@/features/blog/api';
import { getContentBlock } from '@/lib/api';
import LoginModal from '@/shared/ui/LoginModal';

// TYPES
type Tab = 'dashboard' | 'tours' | 'bookings' | 'reviews' | 'guides' | 'blog' | 'content';

interface BookingItem {
  id: string;
  user_name: string;
  user_phone: string;
  status: BookingStatus;
  created_at: Date | string;
  tickets_adult: number;
  tickets_child: number;
  event_id: string;
  tour?: { title: string; date: Date | string };
}

interface GuideItem extends Omit {
  id: string;
}

// --- MAIN COMPONENT ---
export default function AdminDashboard({ initialTours }: { initialTours: Tour[] }) {
  const [isAuth, setIsAuth] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const { showToast } = useToast();

  // Data State
  const [tours, setTours] = useState(initialTours);
  const [bookings, setBookings] = useState([]);
  const [guides, setGuides] = useState([]);
  const [posts, setPosts] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [contentBlocks, setContentBlocks] = useState({});

  // Modals
  const [modalState, setModalState] = useState({
    tour: false, guide: false, post: false, content: false, review: false
  });
  const [editingItem, setEditingItem] = useState(null);
  const [editingSlug, setEditingSlug] = useState('');

  // --- INIT ---
  useEffect(() => {
    if (typeof window !== 'undefined' && localStorage.getItem('is_admin') === 'true') {
        setIsAuth(true);
        loadAllData();
    }
  }, []);

  const loadAllData = async () => {
    try {
        const [bRes, gRes, pRes, rRes, heroRes, footerRes] = await Promise.all([
            getRegistrationsAction(),
            getGuides(),
            getBlogPosts(),
            getReviews(),
            getContentBlock('hero'),
            getContentBlock('footer')
        ]);

        if (bRes.data) setBookings(bRes.data as BookingItem[]);
        setGuides(gRes as unknown as GuideItem[]);
        setPosts(pRes);
        setReviews(rRes);
        setContentBlocks({ hero: heroRes, footer: footerRes });
    } catch (error) {
        console.error("Data load error:", error);
        showToast("Ошибка загрузки данных", "error");
    }
  };

  const handleLogin = () => {
    localStorage.setItem('is_admin', 'true');
    setIsAuth(true);
    loadAllData();
  };

  const handleLogout = () => {
    localStorage.removeItem('is_admin');
    setIsAuth(false);
  };

  // --- STATS ---
  const stats = useMemo(() => {
    const newBookings = bookings.filter(b => b.status === 'pending').length;
    const totalTours = tours.length;
    const activeTours = tours.filter(t => t.isActive).length;
    const finishedTours = tours.filter(t => new Date(t.date) < new Date()).length;

    const now = new Date();
    const nextWeek = new Date();
    nextWeek.setDate(now.getDate() + 7);

    const toursThisWeek = tours
        .filter(t => {
            const d = new Date(t.date);
            return d >= now && d <= nextWeek && t.isActive;
        })
        .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return { 
        newBookings, totalTours, activeTours, finishedTours, 
        totalPosts: posts.length, totalGuides: guides.length,
        toursThisWeek 
    };
  }, [bookings, tours, posts, guides]);

  const guidesForForm = useMemo(() => guides.map(g => ({ id: g.id, name: g.name })), [guides]);

  // --- HANDLERS ---

  const toggleTourStatus = async (tour: Tour) => {
    const newStatus = !tour.isActive;
    setTours(prev => prev.map(t => t.id === tour.id ? { ...t, isActive: newStatus } : t));

    // 👇 Используем легкую функцию
    const res = await updateTourStatus(String(tour.id), newStatus);

    if(!res.success) {
        showToast("Ошибка обновления", "error");
        setTours(prev => prev.map(t => t.id === tour.id ? { ...t, isActive: !newStatus } : t));
    }
  };

  const handleSendTg = async (tourId: string, title: string) => {
      const list = bookings.filter(b => b.event_id === tourId && b.status !== 'cancelled');
      if (list.length === 0) return showToast('Список пуст', 'error');

      let msg = `📋 *Список группы: ${title}*\n\n`;
      list.forEach((b, i) => msg += `${i+1}. ${b.user_name} (${(b.tickets_adult||0)+(b.tickets_child||0)} чел.)\n📞 ${b.user_phone}\n\n`);
      msg += `\n👥 Всего: ${list.reduce((acc, b) => acc + (b.tickets_adult||0) + (b.tickets_child||0), 0)}`;

      const res = await sendToTelegram(msg);
      showToast(res.success ? 'Отправлено в TG!' : 'Ошибка отправки', res.success ? 'success' : 'error');
  };

  const handleStatusChange = async (id: string, status: string) => {
      await updateRegistrationStatus(id, status);
      setBookings(prev => prev.map(b => b.id === id ? { ...b, status: status as BookingStatus } : b));
      showToast('Статус обновлен', 'success');
  };

  const handleDelete = async (type: 'tour'|'post'|'guide'|'review', id: string) => {
      if(!confirm('Удалить навсегда?')) return;
      try {
          if(type === 'tour') { await deleteTour(id); setTours(p => p.filter(t => t.id !== id)); }
          if(type === 'post') { await deletePostAction(id); setPosts(p => p.filter(x => x.id !== id)); }
          if(type === 'guide') { await deleteGuideAction(id); setGuides(p => p.filter(x => x.id !== id)); }
          if(type === 'review') { await deleteReview(id); setReviews(p => p.filter(x => x.id !== id)); }
          showToast('Удалено', 'success');
      } catch (e) { showToast('Ошибка удаления', 'error'); }
  };

  const handleFabClick = () => {
      setEditingItem(null);
      if (activeTab === 'tours') setModalState(p => ({...p, tour: true}));
      if (activeTab === 'blog') setModalState(p => ({...p, post: true}));
      if (activeTab === 'guides') setModalState(p => ({...p, guide: true}));
      if (activeTab === 'reviews') setModalState(p => ({...p, review: true}));
  };

  // --- POSTS ---
  const togglePostStatus = async (post: any, field: 'isActive' | 'is_trending') => {
      const newVal = !post[field];
      setPosts(prev => prev.map(p => p.id === post.id ? { ...p, [field]: newVal } : p));
      await savePostAction({ id: post.id, title: post.title, [field === 'isActive' ? 'is_active' : 'is_trending']: newVal });
  };

  // --- REVIEWS ---
  const toggleReviewStatus = async (review: Review) => {
      const newVal = !review.isActive;
      setReviews(prev => prev.map(r => r.id === review.id ? { ...r, isActive: newVal } : r));
      await upsertReview({ ...review, isActive: newVal });
  };

  if (!isAuth) return  {}} onLogin={handleLogin} />;

  return (







        {/* VIEW ROUTER */}
        {activeTab === 'dashboard' && (
             setActiveTab('bookings')}
                onEditTour={(tour) => { setEditingItem(tour); setModalState(p => ({...p, tour: true})); }}
            />
        )}

        {activeTab === 'tours' && (
             { setEditingItem(null); setModalState(p => ({...p, tour: true})); }}
                onEdit={(tour) => { setEditingItem(tour); setModalState(p => ({...p, tour: true})); }}
                onDuplicate={(tour) => { 
                    const { id, ...rest } = tour; 
                    setEditingItem({...rest, title: `${rest.title} (Копия)`, isActive: false, slug: ''}); 
                    setModalState(p => ({...p, tour: true})); 
                }}
                onDelete={(id) => handleDelete('tour', id)}
                onToggleStatus={toggleTourStatus}
                onSendTg={handleSendTg}
            />
        )}

        {activeTab === 'bookings' && (

        )}

        {activeTab === 'reviews' && (
             { setEditingItem(null); setModalState(p => ({...p, review: true})); }}
                onEdit={(r) => { setEditingItem(r); setModalState(p => ({...p, review: true})); }}
                onDelete={(id) => handleDelete('review', id)}
                onToggleStatus={toggleReviewStatus}
            />
        )}

        {activeTab === 'guides' && (
             { setEditingItem(null); setModalState(p => ({...p, guide: true})); }}
                onEdit={(g) => { setEditingItem(g); setModalState(p => ({...p, guide: true})); }}
                onDelete={(id) => handleDelete('guide', id)}
            />
        )}

        {activeTab === 'blog' && (
             { setEditingItem(null); setModalState(p => ({...p, post: true})); }}
                onEdit={(post) => { setEditingItem(post); setModalState(p => ({...p, post: true})); }}
                onDuplicate={(post) => { 
                    const { id, ...rest } = post; 
                    setEditingItem({ ...rest, title: `${rest.title} (Копия)`, slug: '' }); 
                    setModalState(p => ({...p, post: true})); 
                }}
                onDelete={(id) => handleDelete('post', id)}
                onToggleStatus={togglePostStatus}
            />
        )}

        {activeTab === 'content' && (
             { 
                setEditingSlug(slug); 
                setModalState(p => ({...p, content: true})); 
            }} />
        )}



      {/* МОДАЛКИ (Остались в родителе, так как они глобальные) */}
      {modalState.tour && (
         setModalState(p => ({ ...p, tour: false }))}
            onSuccess={async () => {
                // 1. Закрываем модалку
                setModalState(p => ({ ...p, tour: false }));

                // 2. МЯГКОЕ ОБНОВЛЕНИЕ
                // Вместо перезагрузки страницы мы просто просим React 
                // заново сходить на сервер и обновить списки в памяти.
                await loadAllData(); 

                // 3. (Опционально) Показываем уведомление, если его нет внутри loadAllData
                showToast('Тур успешно сохранен', 'success');
            }}
        />
      )}

      {modalState.guide && (
           setModalState(p => ({ ...p, guide: false }))}
            onSubmit={async (data) => { await saveGuideAction(data); loadAllData(); }}
          />
      )}

      {modalState.post && (
           setModalState(p => ({ ...p, post: false }))}
            onSubmit={async (data) => { await savePostAction(data); loadAllData(); }}
          />
      )}

      {modalState.review && (
           setModalState(p => ({ ...p, review: false }))}
            onSuccess={() => { setModalState(p => ({ ...p, review: false })); loadAllData(); showToast('Отзыв сохранен', 'success'); }}
          />
      )}

      {modalState.content && (
           setModalState(p => ({ ...p, content: false }))}
            onSubmit={async (s, d) => { await saveContentBlockAction(s, d); loadAllData(); }}
          />
      )}



  );
}



"use client";

import React from 'react';
import { 
  LayoutTemplate, Compass, Users, 
  MessageCircle, FileText, Layout, 
