interface Props {
  isOpen: boolean;
  onClose: () => void;
  onApply: (data: any) => void;
}

export default function AiModal({ isOpen, onClose, onApply }: Props) {
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);

    // Выполняем запрос к AI
    const res = await performAiTask({ mode: 'generate_tour', prompt });

    setLoading(false);

    if (res.success) {
      onApply(res.data);
      onClose();
      setPrompt('');
    } else {
      alert("Ошибка AI: " + res.error);
    }
  };

  if (!isOpen) return null;

  return (
    // ✅ ИСПРАВЛЕНИЕ: z-[100] гарантирует, что это окно будет ВЫШЕ формы создания тура (у которой z-50)



      {/* Кликабельный оверлей для закрытия (по желанию) */}






