            AI Генератор Тура

           { e.stopPropagation(); onClose(); }} 
            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition p-1 hover:bg-slate-100 rounded-lg"
          >




        {/* Body */}




            Опишите в двух словах, какой тур вы хотите создать (локация, сложность, фишки), и AI подготовит черновик.


           setPrompt(e.target.value)}
            className="w-full h-32 p-4 text-sm bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-violet-500/20 focus:border-violet-500 outline-none resize-none dark:text-white placeholder:text-slate-400 transition-all"
            placeholder="Например: Семейный поход на байдарках по Днестру на 2 дня с ночевкой в палатках и мастер-классом по выживанию..."
            autoFocus
          />


        {/* Footer */}


           { e.stopPropagation(); onClose(); }} 
            disabled={loading}
            className="bg-white hover:bg-slate-100"
          >
            Отмена


            {loading ?  : }
            Сгенерировать





  );
}



"use client";

import React, { useState, useEffect } from 'react';
import { X, Save, Upload, Loader2, Sparkles, Wand2, Link as LinkIcon, Mail, Phone, Instagram, Send } from 'lucide-react';
import Button from '@/shared/ui/Button';
import { uploadImage } from '@/lib/api'; // Наша функция загрузки
import { performAiTask } from '@/features/admin/actions/ai'; // AI для текстов

interface Props {
  slug: string; // 'hero' или 'footer'
  initialContent: any;
  onClose: () => void;
  onSubmit: (slug: string, data: any) => Promise;
}

export default function ContentForm({ slug, initialContent, onClose, onSubmit }: Props) {
  const [data, setData] = useState({});
  const [uploading, setUploading] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    setData(initialContent || {});
  }, [initialContent]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    await onSubmit(slug, data);
    setIsSaving(false);
    onClose();
  };

  const handleChange = (field: string, value: string) => {
    setData((prev: any) => ({ ...prev, [field]: value }));
  };

  // 🖼️ ЗАГРУЗКА ФОНА
  const handleFileUpload = async (e: React.ChangeEvent) => {
    const file = e.target.files?.[0]; if (!file) return;
    setUploading(true);
    try {
        const url = await uploadImage(file);
        if (url) handleChange('bg_image', url);
        else alert("Ошибка загрузки");
    } catch (e) { alert("Ошибка"); } 
    finally { setUploading(false); }
  };

  // 🪄 AI УЛУЧШЕНИЕ ЗАГОЛОВКА
  const handleAiImprove = async (field: string) => {
      if (!data[field]) return;
      setAiLoading(true);
      const res = await performAiTask({ mode: 'improve_text', text: data[field], tone: 'selling' });
      setAiLoading(false);
      if (res.success) handleChange(field, res.data as string);
  };

  const getTitle = () => {
    if (slug === 'hero') return '🏠 Главный экран';
    if (slug === 'footer') return '📞 Контакты и подвал';
    return 'Редактирование';
  };

  return (





        {/* HEADER */}






                  {slug === 'hero' ?  : }
                  {getTitle()}


Настройка контента сайта




        {/* BODY */}


          {/* === HERO SECTION === */}
          {slug === 'hero' && (


              {/* Заголовок с AI */}




                    Заголовок (H1)
                     handleAiImprove('title')} disabled={aiLoading || !data.title} className="text-[10px] text-violet-600 hover:text-violet-700 flex items-center gap-1 font-bold disabled:opacity-50">
                        {aiLoading ?  : } AI Rewrite


                 handleChange('title', e.target.value)} placeholder="Главный слоган..."
                />


              {/* Подзаголовок */}


                Подзаголовок
                 handleChange('subtitle', e.target.value)} placeholder="Описание..."
                />


              {/* ФОН (Картинка) */}


                Фоновое изображение


                    {data.bg_image ? (






Нажми, чтобы заменить


                    ) : (



                            Загрузить фото

                    )}


                {/* Fallback input */}
                 handleChange('bg_image', e.target.value)}
                />


          )}

          {/* === FOOTER SECTION === */}
          {slug === 'footer' && (






                     Email
                     handleChange('email', e.target.value)}
                    />



                     Телефон
                     handleChange('phone', e.target.value)}
                    />




                 Instagram (ссылка)
                 handleChange('instagram', e.target.value)} placeholder="https://instagram.com/..."
                />



                 Telegram (ссылка)
                 handleChange('telegram', e.target.value)} placeholder="https://t.me/..."
                />


          )}

          {/* FOOTER ACTIONS */}


            Отмена

                {isSaving || uploading ?  : } 
                Сохранить





  );
}



