        alert("Ошибка загрузки"); 
    } 
    finally { setLoadingField(null); }
  };

  return (





        {/* HEADER */}








                {initialData ? 'Редактировать досье' : 'Новый оперативник'}





        {/* BODY */}


          {/* --- ФОТОГРАФИИ (GRID) --- */}


             {/* 1. Портрет (Card) */}



                     Портрет (Карточка)



                    {formData.image ? (

                    ) : (



                            Загрузить фото

                    )}


                       {loadingField === 'image' ?  : }

                     handleFile(e, 'image')} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />



             {/* 2. Экшен (Modal) */}



                     Экшен (Модалка)



                    {formData.actionImage ? (

                    ) : (



                            Загрузить фото в деле

                    )}


                       {loadingField === 'actionImage' ?  : }

                     handleFile(e, 'actionImage')} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />







          {/* --- ОСНОВНАЯ ИНФО --- */}




