    if (res.success) {
      onImport(res.data); // Передаем распаршенные данные в TourForm
      onClose();
      setText(''); // Очищаем
    } else {
      alert("Ошибка импорта: " + res.error);
    }
  };

  const handlePaste = async () => {
    try {
      const clipboardText = await navigator.clipboard.readText();
