import React, { useState, useCallback } from 'react';
import { useFormContext } from 'react-hook-form';
import { UploadCloud, X, Loader2, Image as ImageIcon } from 'lucide-react';
import Image from 'next/image';
import { clsx } from 'clsx';
// Импортируем вашу функцию загрузки (проверьте путь, он был в старом файле)
import { uploadFile } from '@/features/admin/upload'; 

interface ImageUploaderProps {
  name: string;      // Имя поля в форме (например "coverImage")
  label?: string;
  className?: string;
  folder?: string;   // Папка в Storage (по дефолту "tours")
}

export const ImageUploader = ({ 
  name, 
  label = "Обложка тура", 
  className,
  folder = "tours" 
}: ImageUploaderProps) => {
  const { setValue, watch, formState: { errors } } = useFormContext();

  // Следим за значением поля (там лежит URL строки)
  const value = watch(name);
  const error = errors[name]?.message as string;

  const [isUploading, setIsUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);

  // === ЛОГИКА ЗАГРУЗКИ ===
  const handleUpload = async (file: File) => {
    // Проверка типа
    if (!file.type.startsWith('image/')) {
      alert("Можно загружать только изображения");
      return;
    }
    // Проверка размера (например 5Мб)
    if (file.size > 5 * 1024 * 1024) {
      alert("Файл слишком большой (макс 5Мб)");
      return;
    }

    try {
      setIsUploading(true);
      // Загружаем в Supabase
      const url = await uploadFile(file, folder);

      if (url) {
        // Записываем полученную ссылку в форму
        setValue(name, url, { shouldDirty: true, shouldValidate: true });
      }
    } catch (e) {
      console.error("Upload error:", e);
      alert("Ошибка загрузки файла");
    } finally {
      setIsUploading(false);
    }
  };

  // === DRAG & DROP ===
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleUpload(e.dataTransfer.files[0]);
    }
  }, []);

  const handleChange = (e: React.ChangeEvent) => {
    if (e.target.files && e.target.files[0]) {
      handleUpload(e.target.files[0]);
    }
  };

  return (



        {label}


      {/* 1. Если картинка уже есть -> Показываем PREVIEW */}
      {value && value.length > 0 ? (




          {/* Кнопка удаления */}
           {
              e.preventDefault();
              setValue(name, null, { shouldDirty: true });
            }}
            className="absolute top-2 right-2 p-2 bg-rose-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity shadow-lg hover:bg-rose-600"
          >





            Загружено


      ) : (
        /* 2. Если картинки нет -> Показываем ЗАГРУЗЧИК */




          {isUploading ? (



              Загрузка...

          ) : (









Нажмите или перетащите фото

JPG, PNG, WEBP (макс 5MB)


          )}

      )}

      {error && 
{error}}

  );
};



