import { createClient } from '@supabase/supabase-js';

// Инициализация клиента Supabase
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);

/**
 * Универсальная функция загрузки файлов в Supabase Storage
 * @param file - Объект файла (из input type="file")
 * @param folder - Папка назначения ('tours', 'docs', 'blog', 'guides'). По умолчанию 'tours'.
 */
export const uploadFile = async (file: File, folder: string = 'tours'): Promise<{ url: string | null; error?: string }> => {
  try {
    // 1. Генерация безопасного имени файла
    // Убираем кириллицу и спецсимволы, добавляем время для уникальности
    const fileExt = file.name.split('.').pop();
    // Оставляем только латинские буквы и цифры в названии, остальное заменяем на "_"
    const safeName = file.name.replace(/\.[^/.]+$/, "").replace(/[^a-zA-Z0-9]/g, "_");
    const fileName = `${Date.now()}_${safeName}.${fileExt}`;

    // Итоговый путь: "tours/1709823_foto.jpg" или "docs/1709823_contract.pdf"
    const filePath = `${folder}/${fileName}`;

    // 2. Загрузка в бакет 'tours-images'
    const { error: uploadError } = await supabase.storage
      .from('tours-images') 
      .upload(filePath, file, {
        upsert: true,
        cacheControl: '3600'
      });

    if (uploadError) {
      console.error('Supabase Upload Error:', uploadError);
      throw uploadError;
    }

    // 3. Получение публичной ссылки
    const { data } = supabase.storage
      .from('tours-images')
      .getPublicUrl(filePath);

    return { url: data.publicUrl };

  } catch (error: any) {
    console.error('Global Upload Error:', error);
    return { url: null, error: error.message || 'Ошибка при загрузке файла' };
  }
};



'use server'

import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'
import { PostFormat } from '@prisma/client'
// 👇 Импорт нашей утилиты для Телеграма
import { sendToTelegram } from '@/features/admin/actions/telegram';

// === 1. СОЗДАНИЕ ПОСТА (ТВОЙ ОРИГИНАЛЬНЫЙ КОД) ===
export async function createBlogPost(formData: FormData) {
  const title = formData.get('title') as string
  const content = formData.get('content') as string
  const category = formData.get('category') as string || 'Разное'
  const image = formData.get('image') as string
  const readTime = parseInt(formData.get('read_time') as string) || 5

  // Получаем формат
  const formatRaw = formData.get('format') as string
  const format = (formatRaw === 'short' || formatRaw === 'long') 
    ? formatRaw as PostFormat 
    : 'long'

  // Новые поля
  const authorName = formData.get('author_name') as string || 'Команда EVA'
  const authorRole = formData.get('author_role') as string || 'Гид клуба'
  const authorImage = formData.get('author_image') as string || ''

  // Генерация Excerpt
  let excerpt = formData.get('excerpt') as string
  if (!excerpt && content) {
     const plainText = content.replace(/<[^>]+>/g, '')
     excerpt = plainText.slice(0, 150) + '...'
  }

  // Генерация slug
  const slug = title
    .toLowerCase()
    .trim()
    .replace(/[^\w\u0400-\u04FF\s-]/gi, '')
    .replace(/\s+/g, '-') 
    + '-' + Date.now().toString().slice(-4)

  try {
    await prisma.blog.create({
      data: {
        title,
        content,
        slug,
        category,
        image,
        read_time: readTime,
        is_trending: formData.get('is_trending') === 'on',
        // Обработка нового поля isActive (если оно придет из формы, иначе false по дефолту)
        isActive: formData.get('is_active') === 'on', 
        excerpt: excerpt || "Интересная история из мира гор",
        format: format,

        author_name: authorName,
        author_role: authorRole,
        author_image: authorImage,
      },
    })

    revalidatePath('/blog')
    revalidatePath('/') 
  } catch (error) {
    console.error("Ошибка при создании поста:", error)
  }

  redirect('/admin')
}

// === 2. НОВАЯ ФУНКЦИЯ: ОТПРАВКА ПРЕДЛОЖЕНИЯ В TELEGRAM ===
export async function sendProposalAction(data: { name: string, contact: string, type: string, message: string }) {
  const { name, contact, type, message } = data;

  const text = `
📬 Новое предложение в Блог!

👤 Автор: ${name}
📞 Связь: ${contact}
💡 Тип: ${type === 'post' ? 'Готовая статья' : 'Идея / Тема'}

📝 Суть:
${message}
  `;

  // Отправляем в Telegram (используем твой готовый хелпер)
  return await sendToTelegram(text);
}



"use server"; 
import { prisma } from '@/lib/prisma';

export async function getBlogPosts() {
  try {
    const posts = await prisma.blog.findMany({
      orderBy: {
        date: 'desc', // Или createdAt, если используете его
      },
      // 👇 ВАЖНО: Подтягиваем данные связанного гида
      include: {
        guide: {
          select: {
            id: true,
            name: true,
            image: true,
            role: true
          }
        }
      }
    });
    return posts;
  } catch (error) {
    console.error('Ошибка при получении постов:', error);
    return [];
  }
}

// Также полезно добавить функцию получения одного поста по slug с гидом
export async function getBlogPostBySlug(slug: string) {
  try {
    const post = await prisma.blog.findUnique({
      where: { slug },
      include: {
        guide: {
          select: {
            id: true,
            name: true,
            image: true,
            role: true,
            bio: true,
            instagram: true
          }
        }
      }
    });
    return post;
  } catch (error) {
    console.error(`Ошибка при получении поста ${slug}:`, error);
    return null;
  }
}



