'use server';

import { createClient } from '@/utils/supabase/server';
import { revalidatePath } from 'next/cache';
import { Tour } from './types';

// Хелпер для генерации slug
function generateSlug(title: string): string {
  const trans: Record = {
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ё': 'yo', 'ж': 'zh',
    'з': 'z', 'и': 'i', 'й': 'y', 'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n', 'о': 'o',
    'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f', 'х': 'h', 'ц': 'ts',
    'ч': 'ch', 'ш': 'sh', 'щ': 'sch', 'ъ': '', 'ы': 'y', 'ь': '', 'э': 'e', 'ю': 'yu',
    'я': 'ya'
  };
  const slug = title.toLowerCase().split('').map(c => trans[c] || c).join('');
  return slug.trim().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-') + '-' + Date.now().toString().slice(-4);
}

// ✅ ГЛАВНЫЙ МАППЕР (UI Type -> DB Columns)
function mapTourToDb(data: Partial) {
  // 1. Подготовка JSON полей
  // Prisma/Supabase ожидают валидный JSON, убедимся, что это не undefined
  const programDb = data.program ?? [];
  const highlightsDb = data.highlights ?? [];
  const faqDb = data.faq ?? [];
  const checklistDb = data.checklist ?? [];
  const documentsDb = data.documents ?? [];
  const datesDb = data.dates ?? [];

  // 2. Извлечение ID гида
  // В форме мы можем получить объект guide или просто guide_id в датах
  // Приоритет: data.guide.id -> затем берем из первой даты -> или null
  const guideId = data.guide?.id ?? data.dates?.[0]?.guide_id ?? null;

  return {
    // Основное
    title: data.title,
    subtitle: data.subtitle,
    slug: data.slug,
    is_active: data.isActive, // DB: is_active

    // Маркетинг
    type: data.type || 'hiking',
    difficulty: data.difficulty || 'medium',
    label: data.label,
    tags: data.tags, // DB: tags (array)

    // Логистика
    location: data.location,
    route: data.route,
    distance: data.distance,
    duration: data.duration,
    meeting_point: data.meetingPoint, // DB: meeting_point

    // Даты и Гид
    dates: datesDb,   // DB: dates (jsonb)
    guide_id: guideId, // DB: guide_id

    // Финансы (Разворачиваем объект price)
  currency: data.currency || 'RUB',

    // 2. Основная цена (бывшее adult)
    price: data.price ?? 0,
    price_old: data.priceOld ?? null,
    price_child: data.priceChild ?? null,
    price_family: data.priceFamily ?? null,
    price_member: data.priceMember ?? null,

    // Места
    spots: Number(data.spots ?? 15),
    spots_left: Number(data.spotsLeft ?? 15), // DB: spots_left

    // Медиа
    cover_image: data.image, // DB: cover_image (mapped from UI 'image')
    gallery: data.gallery,

    // Контент и Списки
    description: data.description,
    highlights: highlightsDb,
    program: programDb,

    included: data.included,
    additional_expenses: data.additionalExpenses, // DB: additional_expenses

    checklist: checklistDb,
    documents: documentsDb,
    faq: faqDb,

    // SEO
    meta_title: (data as any).meta_title, // Если поля нет в типе Tour, кастуем
    meta_desc: (data as any).meta_desc,
  };
}

// 1. СОЗДАНИЕ
export async function createTour(data: Partial) {
  const supabase = await createClient();

  try {
    const slug = data.slug || generateSlug(data.title || 'new-tour');

    const dbPayload = {
      ...mapTourToDb(data),
      slug,
      // При создании форсируем некоторые дефолты
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };

    // Очищаем undefined значения, чтобы Postgres использовал дефолты
    const cleanedPayload = Object.fromEntries(
      Object.entries(dbPayload).filter(([_, v]) => v !== undefined)
    );

    // ⚠️ ВАЖНО: Пишем в таблицу 'tours' (новая модель), а не 'events'
    const { data: inserted, error } = await supabase
      .from('tours') 
      .insert(cleanedPayload)
      .select()
      .single();

    if (error) {
        console.error("Supabase Create Error:", error);
        throw new Error(error.message);
    }

    revalidatePath('/admin');
    revalidatePath('/');
    return { success: true, data: inserted };

  } catch (error: any) {
    console.error('Create Tour Error:', error);
    return { success: false, error: error.message };
  }
}

// 2. ОБНОВЛЕНИЕ
export async function updateTour(id: string, data: Partial) {
  const supabase = await createClient();

  try {
    const dbPayload = mapTourToDb(data);

    const cleanedPayload = Object.fromEntries(
      Object.entries(dbPayload).filter(([_, v]) => v !== undefined)
    );

    // Добавляем update timestamp
    (cleanedPayload as any).updated_at = new Date().toISOString();

    const { error } = await supabase
      .from('tours')
      .update(cleanedPayload)
      .eq('id', id);

    if (error) throw new Error(error.message);

    revalidatePath('/admin');
    if (data.slug) revalidatePath(`/tour/${data.slug}`);
    revalidatePath('/');

    return { success: true };

  } catch (error: any) {
    console.error('Update Tour Error:', error);
    return { success: false, error: error.message };
  }
}

// 3. УДАЛЕНИЕ
export async function deleteTour(id: string) {
  const supabase = await createClient();
  // Удаляем из таблицы 'tours'
  const { error } = await supabase.from('tours').delete().eq('id', id);

  if (error) {
      console.error("Delete Error:", error);
      return { success: false, error: error.message };
  }

  revalidatePath('/admin');
  return { success: true };
}



"use server";

import { prisma } from '@/lib/prisma';
import { Tour } from './types'; 

// ==========================================
// 1. АДАПТЕР (Prisma DB -> Frontend Type)
// ==========================================
function mapPrismaTourToFrontend(item: any): Tour {
  // 1. Работаем с датами (защита от null)
  const dates = Array.isArray(item.dates) ? item.dates : [];
  const firstDate = dates[0] || {};

  // 2. Хелпер для JSON полей (гарантирует массив)
  const ensureArray = (val: any) => Array.isArray(val) ? val : [];

  return {
    id: item.id,
    slug: item.slug,
    title: item.title,
    subtitle: item.subtitle || null,

    // 👇 ВОЗВРАЩАЕМ СЫРОЕ ОПИСАНИЕ
    description: item.description || "",

    type: item.type,
    difficulty: item.difficulty || 'medium',
    label: item.label || null,
    tags: item.tags || [], // Prisma возвращает массив строк, всё ок

    location: item.location,
    // Формируем строковые даты для карточки
    date: firstDate.start ? new Date(firstDate.start).toISOString() : '', 
    // 👇 БЕРЕМ ДАТУ КОНЦА ИЗ ПЕРВОЙ ДАТЫ МАССИВА
    endDate: firstDate.end ? new Date(firstDate.end).toISOString() : null,

    // 👇 ВОЗВРАЩАЕМ ПОЛНЫЙ МАССИВ ДАТ
    dates: dates,

    duration: item.duration || null,
    distance: item.distance || null,
    meetingPoint: item.meetingPoint || null,

    // 👇 ДОБАВЛЕНО: Маршрут
    route: item.route || null,

    // === ФИНАНСЫ (Исправлено: везде используем item) ===
   // ...
    // === ФИНАНСЫ ===
    price: Number(item.price) || 0,
    currency: item.currency || 'RUB',

    // 🔥 ФИКС: Проверяем оба варианта написания (camelCase и snake_case)
    // Prisma после 'db pull' может вернуть как item.price_old, так и item.priceOld
    priceOld: item.priceOld ? Number(item.priceOld) : (item.price_old ? Number(item.price_old) : null),

    priceChild: item.priceChild ? Number(item.priceChild) : (item.price_child ? Number(item.price_child) : null),

    priceFamily: item.priceFamily ? Number(item.priceFamily) : (item.price_family ? Number(item.price_family) : null),

    priceMember: item.priceMember ? Number(item.priceMember) : (item.price_member ? Number(item.price_member) : null),
    // ...

    // === СТАТИСТИКА ===
    spots: item.spots || 15,
    spotsLeft: item.spotsLeft ?? item.spots ?? 15,

    // Медиа
    image: item.coverImage || null, // UI ждет image
    gallery: item.gallery || [],

    // 👇 БЕЗОПАСНЫЙ МАППИНГ JSON ПОЛЕЙ
    program: item.program, 
    faq: ensureArray(item.faq),
    highlights: ensureArray(item.highlights),
    checklist: ensureArray(item.checklist),
    documents: ensureArray(item.documents),

    included: item.included || [],
    additionalExpenses: item.additionalExpenses || [],

    // Гид (привязанный к туру)
    guide: item.guide ? {
      id: item.guide.id,
      name: item.guide.name,
      image: item.guide.image,
      role: item.guide.role,
      instagram: item.guide.instagram,
      bio: item.guide.bio,
      telegram: item.guide.telegram // Добавили телеграм, если есть
    } : null,

    isActive: item.isActive,
  };
}

// ==========================================
// 2. ПОЛУЧИТЬ АКТИВНЫЕ ТУРЫ (Для сайта)
// ==========================================
export async function getTours() {
  try {
    const tours = await prisma.tour.findMany({
      where: { isActive: true },
      orderBy: { createdAt: 'desc' },
      include: { guide: true } // 🔥 ВАЖНО: Подгружаем гида
    });

    return tours.map(mapPrismaTourToFrontend);
  } catch (error) {
    console.error("Ошибка получения туров:", error);
    return [];
  }
}

// ==========================================
// 3. ПОЛУЧИТЬ ОДИН ТУР (По Slug)
// ==========================================
export async function getTourBySlug(slug: string) {
  try {
    const tour = await prisma.tour.findUnique({
      where: { slug: slug },
      include: { guide: true } // 🔥 ВАЖНО: Подгружаем гида
    });

    if (!tour) return null;
    return mapPrismaTourToFrontend(tour);
  } catch (error) {
    console.error(`Ошибка получения тура ${slug}:`, error);
    return null;
  }
}

// ==========================================
// 4. СОЗДАТЬ БРОНЬ (Booking Action)
// ==========================================
export async function createBookingAction(params: {
    eventId: string;
    name: string;
    phone: string;
    tickets: { adult: number; child: number; family?: number };
    totalPrice: number;
    bookedDate?: Date | null; 
}) {
  try {
    const booking = await prisma.booking.create({
      data: {
        tourId: params.eventId,
        name: params.name,
        phone: params.phone,
        tickets: params.tickets as any,
        totalPrice: params.totalPrice,
        status: 'pending',
        bookedDate: params.bookedDate, 
      }
    });

    return { success: true, data: booking };
  } catch (error: any) {
    console.error("❌ Ошибка бронирования:", error.message);
    return { success: false, error: "Не удалось создать бронь" };
  }
}

export const bookEvent = createBookingAction;

// ==========================================
// 5. ПОЛУЧИТЬ СПИСОК ГИДОВ
// ==========================================
export async function getGuides() {
  try {
    const guides = await prisma.guide.findMany({
      where: { isActive: true },
      select: { id: true, name: true, image: true, role: true },
      orderBy: { name: 'asc' }
    });
    return guides;
  } catch (error) {
    console.error("Ошибка загрузки гидов:", error);
    return [];
  }
}

// ==========================================
// 6. ВСЕ ТУРЫ (Для Админки)
// ==========================================
export async function getAllTours() {
  try {
    const tours = await prisma.tour.findMany({
      orderBy: { createdAt: 'desc' },
      include: { guide: true } 
    });

    return tours.map(mapPrismaTourToFrontend);
  } catch (error) {
    console.error("Ошибка получения всех туров для админки:", error);
    return [];
  }
}



