"use client";

import React, { useState } from 'react';
import { Share2, Printer, MessageCircle, MousePointerClick, Check } from 'lucide-react';
import { Tour } from '@/features/tours/types';

interface TourActionButtonsProps {
  tour: Tour;
}

export default function TourActionButtons({ tour }: TourActionButtonsProps) {
  const [isCopied, setIsCopied] = useState(false);

  // Логика "Поделиться"
  const handleShare = async () => {
    const shareData = {
      title: tour.title,
      text: `Посмотри этот тур: ${tour.title}`,
      url: window.location.href,
    };

    // Если браузер поддерживает нативный шеринг (мобилки)
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      // Иначе просто копируем ссылку
      navigator.clipboard.writeText(window.location.href);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  // Логика "Печать / PDF"
  const handlePrint = () => {
    window.print();
  };

  // Логика "Написать"
  const handleContact = () => {
    // Здесь можно поставить ссылку на WhatsApp или Telegram менеджера
    // window.open('https://t.me/your_manager', '_blank');
    window.location.href = 'mailto:info@your-agency.com';
  };

  return (



      {/* 1. ЗАГОЛОВОК С ИКОНКОЙ */}








           Другие действия



      {/* 2. СЕТКА КНОПОК */}



        {/* КНОПКА: ПОДЕЛИТЬСЯ */}



             {isCopied ?  : }




               {isCopied ? 'Ссылка скопирована' : 'Позвать друзей'}


               Поделиться туром




        {/* КНОПКА: PDF / ПЕЧАТЬ */}








               Документ


               Версия для печати / PDF




        {/* КНОПКА: ВОПРОСЫ */}








               Есть вопросы по туру?


               Напишите нам






  );
}



"use client";

import React, { useEffect, useState } from 'react';
