interface TourBottomActionsProps {
  tour: Tour;
  onBook: () => void;
}

export default function TourBottomActions({ tour, onBook }: TourBottomActionsProps) {
  const [isVisible, setIsVisible] = useState(false);
  const [showHint, setShowHint] = useState(false); // Состояние подсказки

  // Показываем меню только когда проскролили первый экран
  useEffect(() => {
    const handleScroll = () => {
      const heroHeight = window.innerHeight * 0.8;
      setIsVisible(window.scrollY > heroHeight);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (!tour) return null;

  // --- ЛОГИКА ЦЕНЫ ---
  const prices = [
    { label: 'Взрослый', value: tour.price },
    { label: 'Клубная', value: tour.priceMember },
    { label: 'Детский', value: tour.priceChild },
    { label: 'Семейный', value: tour.priceFamily }
  ].filter((p) => typeof p.value === 'number' && p.value > 0);

  // Находим минимальную для отображения "ОТ ..."
  const minPrice = Math.min(...prices.map(p => p.value as number));
  const hasMultiplePrices = prices.length > 1;

  const isSoldOut = (tour.spotsLeft || 0) <= 0;

  return (
    <>
      {/* 1. ПРОЗРАЧНАЯ ПОДЛОЖКА (Чтобы закрыть тултип кликом мимо) */}
      {showHint && (

 setShowHint(false)} 
        />
      )}

      {/* 2. ЛИПКОЕ МЕНЮ */}


        {/* --- ВСПЛЫВАЮЩАЯ ПОДСКАЗКА (TOOLTIP) --- */}




                Все тарифы
                 setShowHint(false)}>



                {prices.map((p, idx) => (


                        {p.label}

                            {(p.value as number).toLocaleString()} {tour.currency}


                ))}

            {/* Стрелочка вниз */}








          {/* БЛОК ЦЕНЫ */}




              Стоимость участия






                    {hasMultiplePrices && от}

                    {minPrice.toLocaleString()}

                    {tour.currency || 'RUB'}


                {/* КНОПКА "i" (Только если есть варианты) */}
                {hasMultiplePrices && (
                     setShowHint(!showHint)}
                        className={clsx(
