interface TourFAQProps {
  tour: Tour;
}

export default function TourFAQ({ tour }: TourFAQProps) {
  // 1. Безопасное извлечение данных
  // В базе данных faq может лежать как JSON-объект, массив или null
  const faqItems = React.useMemo(() => {
    if (!tour.faq) return [];
    if (Array.isArray(tour.faq)) return tour.faq;
    if (typeof tour.faq === 'object' && tour.faq.items) return tour.faq.items;
    return [];
  }, [tour.faq]);

  const [openIndex, setOpenIndex] = useState(0);

  const toggleItem = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  // Если вопросов нет, просто не рисуем блок
  if (faqItems.length === 0) return null;

  return (



      {/* ЗАГОЛОВОК */}








           Частые вопросы



      {/* СПИСОК ВОПРОСОВ (Аккордеон) */}


        {faqItems.map((item: any, index: number) => {
          const isOpen = openIndex === index;
          const question = item.question || item.q || "Вопрос без заголовка";
          const answer = item.answer || item.a || "Ответ уточняется...";

          return (


               toggleItem(index)}
                className="w-full flex items-center justify-between p-5 md:p-6 text-left focus:outline-none group"
              >

                  {question}




                  {isOpen ?  : }




                {isOpen && (





                        {answer}



                )}


          );
        })}



  );
}



"use client";

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import { motion, AnimatePresence } from 'framer-motion';
import { Camera, X, ChevronLeft, ChevronRight, Maximize2 } from 'lucide-react';

interface TourGalleryProps {
  images?: string[];
}

export default function TourGallery({ images = [] }: TourGalleryProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);

  if (!images || images.length === 0) return null;

  const displayedImages = images.slice(0, 5);
  const remainingCount = images.length - 5;

  const openLightbox = (index: number) => {
    setCurrentIndex(index);
    setIsOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setIsOpen(false);
    document.body.style.overflow = 'auto';
  };

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;
      if (e.key === 'Escape') closeLightbox();
      if (e.key === 'ArrowRight') nextImage();
      if (e.key === 'ArrowLeft') prevImage();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  // 🔥 УБРАН margin-bottom
  return (











           Галерея






        {displayedImages.map((img, index) => {
          const isMain = index === 0;
          const isLastVisible = index === 4;

          return (

 openLightbox(index)}
              className={`relative group cursor-pointer overflow-hidden bg-slate-800 ${
                isMain 
                  ? "col-span-2 md:col-span-2 md:row-span-2" 
                  : "col-span-1"
              }`}
            >


              {isLastVisible && remainingCount > 0 ? (


                     +{remainingCount}

              ) : (




              )}

          );
        })}



        {isOpen && (





             e.stopPropagation()}
            >












               {currentIndex + 1} / {images.length}



        )}



  );
}



"use client";

import React from 'react';
import Image from 'next/image';
import { MapPin, Clock, Calendar } from 'lucide-react';
import { Tour } from '@/features/tours/types';

// 1. СЛОВАРЬ ТИПОВ
// Если ключ есть - берем перевод. Если нет - берем значение из базы.
const TYPE_MAP: Record = {
  hiking: 'Поход',
  water: 'Сплав',
  auto: 'Автотур',
  excursion: 'Экскурсия',
  kids: 'Детский',
  // 'weekend', 'выходной день' и прочее выведутся как есть
};

interface TourHeroProps {
  tour: Tour;
}

export default function TourHero({ tour }: TourHeroProps) {

  // --- ЛОГИКА ДАТ (Без изменений, ваш код) ---
  const renderDateRange = () => {
    if (!tour.date) return 'Дата уточняется';

    const startDate = new Date(tour.date);
    const ruDate = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long' });
    const dayOnly = new Intl.DateTimeFormat('ru-RU', { day: 'numeric' });

    if (!tour.endDate) return ruDate.format(startDate);

    const endDate = new Date(tour.endDate);
    if (startDate.getMonth() === endDate.getMonth()) {
       return `${dayOnly.format(startDate)} — ${ruDate.format(endDate)}`;
    }
    return `${ruDate.format(startDate)} — ${ruDate.format(endDate)}`;
  };

  const getDuration = () => {
    if (tour.duration) return tour.duration;
    if (tour.date && tour.endDate) {
      const start = new Date(tour.date).getTime();
      const end = new Date(tour.endDate).getTime();
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1;
      return `${days} дней`;
    }
    return '1 день';
  };

  // --- ЛОГИКА МЕТКИ (TYPE) ---
  // Пробуем словарь, иначе база
  const typeLabel = tour.type 
    ? (TYPE_MAP[tour.type.toLowerCase()] || tour.type) 
    : 'Путешествие';

  return (



      {/* 1. ФОН (Ваш код) */}









      {/* 2. КОНТЕНТ */}






            {/* --- БЕЙДЖИ (ИСПРАВЛЕНО) --- */}



              {/* 1. ТИП ТУРА (Всегда первый) */}
              {/* Стиль: Бирюзовый фон, темный текст (как на скрине) */}

                  {typeLabel}


              {/* 2. МАРКЕТИНГОВАЯ МЕТКА (LABEL) - Только если есть */}
              {/* Стиль: Прозрачный/Серый фон, белый текст (как "Средний" на скрине, но теперь тут Label) */}
              {tour.label && (

                    {tour.label}

              )}


            {/* ЗАГОЛОВОК */}


              {tour.title}


            {/* ПОДЗАГОЛОВОК */}
            {tour.subtitle && (


                {tour.subtitle}

            )}

            {/* --- НИЖНИЙ БЛОК ИНФОРМАЦИИ (КАК БЫЛО) --- */}
            {/* Линия сверху, 3 элемента в ряд */}





                    {/* Локация */}









Локация

{tour.location}



                    {/* Даты */}









Даты

{renderDateRange()}



                    {/* Длительность */}









Длительность

{getDuration()}









  );
}



