              {/* Детская цена */}
              {(priceChild ?? 0) > 0 && (





                    Детский (до 12)


                    {priceChild?.toLocaleString()} {currency}


              )}

               {/* Семейная цена */}
               {(priceFamily ?? 0) > 0 && (





