import React from 'react';
import { Ruler, Signal, Users, Hash } from 'lucide-react';
import { Tour } from '@/features/tours/types';

interface TourStatsProps {
  tour: Tour;
}

export default function TourStats({ tour }: TourStatsProps) {
  if (!tour) return null;

  // 1. СЛОЖНОСТЬ
  const difficultyMap: Record = {
    easy: 'Легкий',
    medium: 'Средний',
    hard: 'Сложный',
    expert: 'Экстрим',
  };

  // ЛОГИКА: Ищем перевод. Если нет — выводим то, что пришло из базы. Если пусто — прочерк.
  const difficultyLabel = tour.difficulty 
    ? (difficultyMap[tour.difficulty.toLowerCase()] || tour.difficulty) 
    : '—';

  // 2. ТИП ТУРА
  const typeMap: Record = {
    hiking: 'Поход',
    water: 'Сплав',
    auto: 'Автотур',
    excursion: 'Экскурсия',
  };
  // ЛОГИКА: Та же самая. Если пришло "выходной день" — выведем "выходной день".
  const typeLabel = tour.type 
    ? (typeMap[tour.type.toLowerCase()] || tour.type)
    : 'Активный';

  // 3. ТЕГ (Для иконки берем первый, если есть)
  const mainTag = tour.tags && tour.tags.length > 0 ? tour.tags[0] : typeLabel;

  return (



      {/* ДИСТАНЦИЯ */}




        Дистанция
        {tour.distance || '—'}


      {/* СЛОЖНОСТЬ */}




        Сложность
        {/* capitalize делает первую букву заглавной */}
        {difficultyLabel}


      {/* ГРУППА */}




        Группа
        до {tour.groupSize || 15} чел.


      {/* ТИП ТУРА */}




        Тип
        {typeLabel}



  );
}



"use client";

import React, { useState, useEffect } from 'react';
import { AlignJustify, ArrowUp } from 'lucide-react';
import { clsx } from 'clsx';

export default function TourStickyNav() {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      // 🔥 УМЕНЬШИЛ ПОРОГ с 600 до 100.
      // Теперь меню появится, как только вы начнете немного скроллить.
      const show = window.scrollY > 100;
      setIsVisible(show);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const y = element.getBoundingClientRect().top + window.scrollY - 80;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (









           Наверх



          {[
            { id: 'about', label: 'Описание' },
            { id: 'program', label: 'Программа' },
            { id: 'gallery', label: 'Фото' },
            { id: 'dates', label: 'Даты' },
            { id: 'faq', label: 'FAQ' },
          ].map((item) => (
             scrollToSection(item.id)}
              className="text-xs font-bold text-slate-400 hover:text-teal-400 hover:bg-white/5 px-3 py-2 rounded-lg transition-all uppercase tracking-wide"
            >
              {item.label}

          ))}








  );
}



