  subtitle?: string;   // Возможность менять подзаголовок
  limit?: number;      // Если нужно ограничить (например, для Главной)
}

export default function ToursBrowser({ 
    tours = [], 
    title = "Афиша Приключений", 
    subtitle = "Schedule 2026",
    limit 
}: ToursBrowserProps) {
  const [activeCategory, setActiveCategory] = useState('all');
  const [viewMode, setViewMode] = useState<'grid' | 'calendar'>('grid');
  const [searchQuery, setSearchQuery] = useState('');
  const [visibleCount, setVisibleCount] = useState(ITEMS_PER_PAGE);

  // Сброс пагинации при смене фильтров
  useEffect(() => {
    setVisibleCount(ITEMS_PER_PAGE);
  }, [activeCategory, searchQuery, viewMode]);

  // --- ЛОГИКА ФИЛЬТРАЦИИ И СОРТИРОВКИ ---
  const { filteredTours, scheduledTours, comingSoonTours } = useMemo(() => {
    const safeTours = tours || [];

    // 1. Фильтрация
    const filtered = safeTours.filter(tour => {
      const matchesCategory = activeCategory === 'all' 
        ? true 
        : tour.type?.toLowerCase() === activeCategory.toLowerCase();

      const matchesSearch = tour.title.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });

    // 2. Разделение
    const scheduled = filtered.filter(t => !!t.date);
    const comingSoon = filtered.filter(t => !t.date); 

    // 3. Сортировка запланированных
    scheduled.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return { filteredTours: filtered, scheduledTours: scheduled, comingSoonTours: comingSoon };
  }, [tours, activeCategory, searchQuery]);

  // Объединенный список для Grid View (сначала даты, потом скоро)
  const gridItems = useMemo(() => {
      return [...scheduledTours, ...comingSoonTours];
  }, [scheduledTours, comingSoonTours]);

  // Применяем лимит (если передан проп limit) или пагинацию
  const displayedGridItems = limit 
      ? gridItems.slice(0, limit) 
      : gridItems.slice(0, visibleCount);

  const hasMore = !limit && visibleCount < gridItems.length;
  const hasTours = gridItems.length > 0;

  return (



      {/* Background Glow */}






        {/* --- HEADER --- */}





               {subtitle}



                {title}



