// Типы уведомлений
type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: string;
  message: string;
  type: ToastType;
}

interface ToastContextType {
  showToast: (message: string, type?: ToastType) => void;
}

const ToastContext = createContext(undefined);

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

// Провайдер
export const ToastProvider = ({ children }: { children: ReactNode }) => {
  const [toasts, setToasts] = useState([]);

  const showToast = useCallback((message: string, type: ToastType = 'success') => {
    // Создаем уникальный ID
    const id = Math.random().toString(36).substring(2, 9);

    // Добавляем уведомление
    setToasts((prev) => [...prev, { id, message, type }]);

    // Удаляем через 4 секунды
    setTimeout(() => {
      removeToast(id);
    }, 4000);
  }, []);

  const removeToast = (id: string) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  };

  return (

      {children}

      {/* КОНТЕЙНЕР УВЕДОМЛЕНИЙ (FIXED PORTAL) */}



          {toasts.map((toast) => (

              {/* Иконка */}


                {toast.type === 'success' && }
                {toast.type === 'error' && }
                {toast.type === 'info' && }


              {/* Текст */}




                  {toast.type === 'success' ? 'Успешно' : toast.type === 'error' ? 'Ошибка' : 'Информация'}



                  {toast.message}



              {/* Кнопка закрытия */}
               removeToast(toast.id)}
                className="shrink-0 text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors p-1 rounded-md hover:bg-slate-100 dark:hover:bg-white/10"
              >



          ))}



  );
};



