const MenuBar = ({ editor }: { editor: any }) => {
  if (!editor) return null;

  const addImage = () => {
    const url = window.prompt('URL картинки:');
    if (url) editor.chain().focus().setImage({ src: url }).run();
  };

  const setLink = () => {
    const previousUrl = editor.getAttributes('link').href;
    const url = window.prompt('URL ссылки', previousUrl);
    if (url === null) return;
    if (url === '') {
      editor.chain().focus().extendMarkRange('link').unsetLink().run();
      return;
    }
    editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
  };

  const btnClass = (isActive: boolean) => 
    `p-2 rounded-lg transition-colors ${isActive ? 'bg-slate-900 text-white' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-900'}`;

  return (


       editor.chain().focus().toggleBold().run()} className={btnClass(editor.isActive('bold'))} title="Жирный">


       editor.chain().focus().toggleItalic().run()} className={btnClass(editor.isActive('italic'))} title="Курсив">






       editor.chain().focus().toggleHeading({ level: 2 }).run()} className={btnClass(editor.isActive('heading', { level: 2 }))} title="Заголовок H2">


       editor.chain().focus().toggleHeading({ level: 3 }).run()} className={btnClass(editor.isActive('heading', { level: 3 }))} title="Заголовок H3">






       editor.chain().focus().toggleBulletList().run()} className={btnClass(editor.isActive('bulletList'))} title="Маркированный список">


       editor.chain().focus().toggleOrderedList().run()} className={btnClass(editor.isActive('orderedList'))} title="Нумерованный список">












       editor.chain().focus().toggleBlockquote().run()} className={btnClass(editor.isActive('blockquote'))} title="Цитата">






       editor.chain().focus().undo().run()} className={btnClass(false)} title="Отменить">


       editor.chain().focus().redo().run()} className={btnClass(false)} title="Вернуть">



  );
};

interface TiptapProps {
  content: string;
  onChange: (html: string) => void;
  placeholder?: string;
}

// --- ОСНОВНОЙ КОМПОНЕНТ ---
export default function TiptapEditor({ content, onChange, placeholder }: TiptapProps) {
  const editor = useEditor({
    immediatelyRender: false,
    extensions: [
      StarterKit,
      Link.configure({ openOnClick: false }),
      Image,
      Placeholder.configure({
        placeholder: placeholder || 'Начните писать...',
        emptyEditorClass: 'is-editor-empty',
      }),
    ],
    content: content,
    editorProps: {
      attributes: {
        // ⚠️ ИСПРАВЛЕНИЕ: Все классы записаны В ОДНУ СТРОКУ, без переносов (\n)
        class: 'prose prose-sm sm:prose-base max-w-none focus:outline-none min-h-[300px] p-4 text-slate-700 leading-relaxed [&_.is-editor-empty]:before:content-[attr(data-placeholder)] [&_.is-editor-empty]:before:text-red-400 [&_.is-editor-empty]:before:float-left [&_.is-editor-empty]:before:h-0 [&_.is-editor-empty]:before:pointer-events-none',
      },
    },
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML());
    },
  });

  useEffect(() => {
    if (editor && content && editor.isEmpty) {
        editor.commands.setContent(content);
    }
  }, [content, editor]);

  return (





  );
}



// src/utils/date.ts

/**
 * Форматирует даты тура в красивую строку.
 * @example "20 февраля" или "20 — 25 февраля" или "28 февраля — 2 марта"
 */
export function formatTourDate(date: string | Date, endDate?: string | Date | null): string {
  if (!date) return 'Дата уточняется';

  const start = new Date(date);

  // Форматтеры
  const ruDateFull = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long' });
  const ruDayOnly = new Intl.DateTimeFormat('ru-RU', { day: 'numeric' });

  // Если нет конечной даты или она совпадает с начальной
  if (!endDate) {
    return ruDateFull.format(start);
  }

  const end = new Date(endDate);

  // Проверка на валидность дат
  if (isNaN(start.getTime()) || isNaN(end.getTime())) return 'Дата уточняется';

  // Если месяцы совпадают (20 — 25 февраля)
  if (start.getMonth() === end.getMonth()) {
    return `${ruDayOnly.format(start)} — ${ruDateFull.format(end)}`;
  }

  // Если месяцы разные (28 февраля — 2 марта)
  return `${ruDateFull.format(start)} — ${ruDateFull.format(end)}`;
}

/**
 * Вычисляет длительность тура, если она не задана вручную.
 * @example "3 дня"
 */
export function getTourDuration(tour: any): string {
  // 1. Если длительность уже прописана в админке текстом — возвращаем её
  if (tour.duration) return tour.duration;

  // 2. Если есть даты, считаем математически
  if (tour.date && tour.endDate) {
    const start = new Date(tour.date).getTime();
    const end = new Date(tour.endDate).getTime();

    // Разница в миллисекундах -> дни
    const diffTime = Math.abs(end - start);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 

    // Если разница 0 (один день), пишем 1 день. Иначе +1 (включительно)
    const totalDays = diffDays < 1 ? 1 : diffDays + 1;

    return `${totalDays} дн.`;
  }

  return '1 день';
}



import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

// 👇 1. Добавляем async перед function
export async function createClient() {
  // 👇 2. Добавляем await перед cookies()
  const cookieStore = await cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // The `setAll` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing
            // user sessions.
          }
        },
      },
    }
  )
}



